// Thin glue between the vendored OpenSeadragon build and this media's IIIF Image API service
// (info.json generated by internal/media). No build step, no framework — OpenSeadragon is
// loaded as a plain <script> before this one.
document.addEventListener("DOMContentLoaded", () => {
  const el = document.getElementById("iiif-viewer");
  if (!el || typeof OpenSeadragon === "undefined") return;

  OpenSeadragon({
    element: el,
    tileSources: `/api/iiif/${el.dataset.mediaId}/info.json`,
    showNavigationControl: false,
    visibilityRatio: 1,
    constrainDuringPan: true,
    gestureSettingsMouse: { clickToZoom: false },
    // WebGL is the OpenSeadragon 5+ default; the plain 2D canvas renderer is broadly compatible
    // with no meaningful downside for static conservation photos, and avoids a black-canvas
    // failure mode seen on some software-GPU setups.
    drawer: "canvas",
  });
});
